 for(const [id,k] of [['board-width','width'],['board-height','height']])$('#'+id).onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<100||n>50000){toast('沙盘尺寸应在 100–50000 mm 之间');renderInspector();return;}record();if(project.board.outline){const axis=k==='width'?'x':'y',factor=n/project.board[k];project.board.outline=project.board.outline.map(p=>({...p,[axis]:p[axis]*factor}));}const factor=n/project.board[k],axis=k==='width'?'x':'y',radius=k==='width'?'rx':'ry';for(const t of project.terrain||[]){t[axis]*=factor;t[radius]=Math.max(10,Math.min(50000,t[radius]*factor));}project.board[k]=n;changed();fit();};
